def cantor_numbering(N: int) -> str:
    """
    Returns the N-th fraction in the Cantor enumeration of positive rationals
    in reduced form, as a string "numerator/denominator".

    The enumeration follows the diagonal traversal of the infinite grid
    of fractions i/j (i, j >= 1), skipping non-reduced fractions.
    """
    if N <= 0:
        raise ValueError("N must be a positive integer")

    def gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    def totient(n: int) -> int:
        result = n
        temp = n
        p = 2
        while p * p <= temp:
            if temp % p == 0:
                while temp % p == 0:
                    temp //= p
                result -= result // p
            p += 1
        if temp > 1:
            result -= result // temp
        return result

    diagonal = 2
    cumulative = 0
    while True:
        phi = totient(diagonal)
        if cumulative + phi >= N:
            target = N - cumulative  # 1-indexed within this diagonal
            count = 0
            for num in range(1, diagonal):
                if gcd(num, diagonal) == 1:
                    count += 1
                    if count == target:
                        den = diagonal - num
                        return f"{num}/{den}"
            # Should never reach here
        cumulative += phi
        diagonal += 1

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    first_term = True
    for degree, coeff in zip(range(n, -1, -1), coeffs):
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'

        abs_coeff = abs(coeff)

        # Determine variable part
        if degree == 0:
            var_part = ''
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = f'x^{degree}'

        # Determine coefficient part
        if abs_coeff == 1 and degree > 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_coeff)

        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)
        first_term = False

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # The mapping must be bijective and cover all 26 uppercase letters
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    reverse_mapping = {}

    for e_char, o_char in zip(encoded, original):
        # Check consistency of forward mapping
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"
        else:
            mapping[e_char] = o_char

        # Check consistency of reverse mapping (bijection)
        if o_char in reverse_mapping:
            if reverse_mapping[o_char] != e_char:
                return "Failed"
        else:
            reverse_mapping[o_char] = e_char

    # Ensure the mapping covers all 26 letters
    if len(mapping) != 26 or len(reverse_mapping) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Normalise names to upper case for comparison
    scenario = scenario.upper()
    liar_set = {name.upper() for name in liar_count}
    days_set = {day.upper() for day in days_of_week}

    for speaker, stmts in statements.items():
        speaker_upper = speaker.upper()
        for stmt in stmts:
            # Skip statements that mention a day of the week
            words = [w.strip('.,;:!?') for w in stmt.upper().split()]
            if any(word in days_set for word in words):
                continue

            # Prepare statement for parsing
            stmt_clean = stmt.strip().lower()
            if stmt_clean.endswith('.'):
                stmt_clean = stmt_clean[:-1]

            # Determine subject and whether the statement claims guilt
            if stmt_clean.startswith('i am '):
                rest = stmt_clean[5:]
                if rest == 'guilty':
                    subject = speaker_upper
                    guilty_claim = True
                elif rest == 'not guilty':
                    subject = speaker_upper
                    guilty_claim = False
                else:
                    continue  # unrecognised format
            else:
                if ' is ' not in stmt_clean:
                    continue
                parts = stmt_clean.split(' is ')
                if len(parts) != 2:
                    continue
                subject_raw = parts[0].strip()
                subject = subject_raw.upper()
                rest = parts[1]
                if rest == 'guilty':
                    guilty_claim = True
                elif rest == 'not guilty':
                    guilty_claim = False
                else:
                    continue

            # Evaluate truth of the statement
            if subject == scenario:
                truth = guilty_claim
            else:
                truth = not guilty_claim

            # Check consistency with liar status
            if speaker_upper in liar_set:
                if truth:  # liar cannot tell truth
                    return False
            else:
                if not truth:  # truth-teller cannot lie
                    return False

    return True

